for file in $(grep -r "\*store\.Memo\|store\.Memo{" /bench/home/work --include="*.go" -l | sort -u); do
  echo "$file"
done | awk -F/ '{
  if ($1 == "" && $2 == "bench" && $3 == "home" && $4 == "work") {
    if ($5 == "store") {
      if ($6 == "db") {
        print $5 "/" $6 "/" $7
      } else if ($6 == "test") {
        print $5 "/" $6
      } else {
        print $5
      }
    } else {
      for(i=5; i<NF; i++) {
        if ($i != "") printf "%s/", $i
      }
      print ""
    }
  }
}' | sort -u
